/// <summary>
/// Data job to populate new Free Text Invoice id field 
/// </summary>
class METALMSupplierVolumetricRebateUpdate
{
}

Method.Source:
    /// <summary>
    /// Runs the class with the specified arguments.
    /// </summary>
    /// <param name = "_args">The specified arguments.</param>
    public static void main(Args _args)
    {
        METALMSupplierVolumetricRebateUpdate instance;

        instance = new METALMSupplierVolumetricRebateUpdate();
        instance.run();
    }

    /// <summary>
    /// Update the METALMSupplierVolumetricRebateHeader table with the FTI invoice id
    /// </summary>
    public void run()
    {
        METALMSupplierVolumetricRebateHeader    headerUpdate, header;
        CustInvoiceTable                        invoice;
        CustInvoiceId                           invoiceId;
        container                               companyHeaderCon, companyHeaderSingleCon, companyInvoiceCon;
        int                                     i, counter;
        LegalEntityDataAreaId                   company;

        while select crosscompany DataAreaId
            from header
            group by DataAreaId
        {
            companyHeaderCon = companyHeaderCon + [header.DataAreaId];
        }

        for(i=1;i<=conLen(companyHeaderCon);i++)
        {
            company = conPeek(companyHeaderCon, i);

            companyHeaderSingleCon = [company];

            ttsbegin;

            changecompany(company)
            {
                while select forupdate crosscompany:companyHeaderSingleCon headerUpdate
                {
                    companyInvoiceCon = [headerUpdate.CustLegalEntity];
                    
                    invoiceId = "";

                    while select firstonly crosscompany:companyInvoiceCon  invoice
                        where   invoice.PurchOrderFormNum   == headerUpdate.Number
                    {
                        invoiceId = invoice.InvoiceId;
                    }
                    
                    if(invoiceId)
                    {
                        headerUpdate.FreeTextInvoiceId    = InvoiceId;
                        headerUpdate.doUpdate();
                        counter++;
                    }
                }
            }
            ttscommit;
        }

        info(strFmt("@MET:RecordsUpdated",counter));
    }
